-- ── story 1-2a: the client master record ──────────────────────────────────
-- Generated by drizzle-kit (the `client_contacts` table, its indexes, the
-- twelve `clients` address columns) and hand-amended below the marker: the
-- CHECKs, RLS on `client_contacts` (the tenant arm plus the 0041
-- `app.client_id` clause on `client_id`), the session revoke-reason CHECK
-- re-added with `client-departed`, and the post-migration probes (drizzle-kit
-- is blind to all of them; `bun run db:generate` afterwards reports "No
-- schema changes").
--
-- Additive: a new tenant-scoped table and twelve nullable columns. No data is
-- rewritten. No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- Lock cost: re-adding `sessions_revoked_reason_check` takes an ACCESS
-- EXCLUSIVE lock on `sessions` and scans it (as in 0075). The table holds
-- only live sessions and those ended within 30 days (the purge), which is
-- acceptable at deploy. The two `clients` CHECKs scan `clients` (tens of rows).
CREATE TABLE "client_contacts" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"phone" text,
	"roles" text[] DEFAULT '{}'::text[] NOT NULL,
	"is_primary" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "registered_line1" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "registered_line2" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "registered_city" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "registered_state_code" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "registered_pincode" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_contact_name" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_phone" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_line1" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_line2" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_city" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_state" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "return_pincode" text;--> statement-breakpoint
CREATE UNIQUE INDEX "client_contacts_client_email_unique" ON "client_contacts" USING btree ("client_id","email");--> statement-breakpoint
CREATE UNIQUE INDEX "client_contacts_one_primary_unique" ON "client_contacts" USING btree ("client_id") WHERE is_primary;--> statement-breakpoint
CREATE INDEX "client_contacts_tenant_client_idx" ON "client_contacts" USING btree ("tenant_id","client_id");

--> statement-breakpoint
-- ── hand-amended: the clients address CHECKs (migration SQL only) ─────────
-- Mirrored by `ClientsCommand.updateAddresses`, which answers a named 400
-- first. Each group is all-or-none (line2 optional, and absent with its
-- group); nullable columns say IS NULL first (IMPLEMENTATION-GUIDE §3).
-- The registered address takes the 21-5 billing columns' shapes.
ALTER TABLE "clients" ADD CONSTRAINT "clients_registered_address_format" CHECK (
	(
		"registered_line1" IS NULL AND "registered_line2" IS NULL AND "registered_city" IS NULL
		AND "registered_state_code" IS NULL AND "registered_pincode" IS NULL
	) OR (
		"registered_line1" IS NOT NULL AND char_length("registered_line1") BETWEEN 1 AND 200
		AND ("registered_line2" IS NULL OR char_length("registered_line2") BETWEEN 1 AND 200)
		AND "registered_city" IS NOT NULL AND char_length("registered_city") BETWEEN 1 AND 100
		AND "registered_state_code" IS NOT NULL AND "registered_state_code" ~ '^[0-9]{2}$'
		AND "registered_pincode" IS NOT NULL AND "registered_pincode" ~ '^[0-9]{6}$'
	)
);--> statement-breakpoint
-- The return address takes the shipment address shape (`ADDRESS_FIELD_LENGTHS`).
ALTER TABLE "clients" ADD CONSTRAINT "clients_return_address_format" CHECK (
	(
		"return_contact_name" IS NULL AND "return_phone" IS NULL AND "return_line1" IS NULL
		AND "return_line2" IS NULL AND "return_city" IS NULL AND "return_state" IS NULL AND "return_pincode" IS NULL
	) OR (
		"return_contact_name" IS NOT NULL AND char_length("return_contact_name") BETWEEN 1 AND 120
		AND "return_phone" IS NOT NULL AND char_length("return_phone") BETWEEN 1 AND 20
		AND "return_line1" IS NOT NULL AND char_length("return_line1") BETWEEN 1 AND 200
		AND ("return_line2" IS NULL OR char_length("return_line2") BETWEEN 1 AND 200)
		AND "return_city" IS NOT NULL AND char_length("return_city") BETWEEN 1 AND 100
		AND "return_state" IS NOT NULL AND char_length("return_state") BETWEEN 1 AND 100
		AND "return_pincode" IS NOT NULL AND "return_pincode" ~ '^[0-9]{6}$'
	)
);--> statement-breakpoint
-- ── hand-amended: the client_contacts CHECKs ──────────────────────────────
-- The roles vocabulary is pinned against `CLIENT_CONTACT_ROLES`
-- (shared/db/schema.ts) by test/client-master.spec.ts.
ALTER TABLE "client_contacts" ADD CONSTRAINT "client_contacts_name_format" CHECK (
	char_length("name") BETWEEN 1 AND 120 AND "name" = btrim("name")
);--> statement-breakpoint
ALTER TABLE "client_contacts" ADD CONSTRAINT "client_contacts_email_format" CHECK (
	"email" = lower(btrim("email")) AND char_length("email") BETWEEN 3 AND 254 AND strpos("email", '@') > 1
);--> statement-breakpoint
ALTER TABLE "client_contacts" ADD CONSTRAINT "client_contacts_phone_format" CHECK (
	"phone" IS NULL OR (char_length("phone") BETWEEN 1 AND 20 AND "phone" = btrim("phone"))
);--> statement-breakpoint
-- A subset of the vocabulary, with no duplicates (a CHECK cannot hold a
-- subquery, so each role appears at most once by `array_positions`). An
-- empty array is a general contact.
ALTER TABLE "client_contacts" ADD CONSTRAINT "client_contacts_roles_check" CHECK (
	"roles" <@ ARRAY['operations', 'billing', 'returns']::text[]
	AND array_position("roles", NULL) IS NULL
	AND coalesce(cardinality(array_positions("roles", 'operations')), 0) <= 1
	AND coalesce(cardinality(array_positions("roles", 'billing')), 0) <= 1
	AND coalesce(cardinality(array_positions("roles", 'returns')), 0) <= 1
);--> statement-breakpoint
-- ── hand-amended: the session revoke reasons gain `client-departed` ───────
-- Pinned against `SESSION_REVOKE_REASONS` (modules/tenancy/sessions.ts) by test/sessions.spec.ts.
ALTER TABLE "sessions" DROP CONSTRAINT "sessions_revoked_reason_check";--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_revoked_reason_check" CHECK (
	("revoked_at" IS NULL) = ("revoked_reason" IS NULL)
	AND ("revoked_reason" IS NULL OR "revoked_reason" IN (
		'signed-out', 'deactivated', 'role-changed', 'client-suspended', 'refresh-reuse', 'released', 'device-revoked',
		'second-factor-reset', 'second-factor-changed', 'client-departed'
	))
);--> statement-breakpoint
-- ── hand-amended: RLS — the tenant arm plus the 0041 client clause ────────
-- A portal-stamped transaction (`app.client_id` set) sees only its own
-- client's contacts; an operator one (unset) sees the tenant's. No portal
-- route reads contacts (decision 6) — this is defence in depth.
ALTER TABLE "client_contacts" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "client_contacts_tenant_isolation" ON "client_contacts"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0075 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: both address groups set (line2 absent and present),
	-- both cleared; contacts with no role, all three roles, a phone; one
	-- primary beside a non-primary; a session revoked `client-departed`.
	BEGIN
		INSERT INTO "clients" ("id","tenant_id","code","name","status","system_owned",
		                       "registered_line1","registered_city","registered_state_code","registered_pincode",
		                       "return_contact_name","return_phone","return_line1","return_line2","return_city","return_state","return_pincode")
		VALUES (c, t, 'P-0077-A', 'probe a', 'active', false,
		        '1 Probe Road', 'Mumbai', '27', '400001',
		        'Returns desk', '+91 98200 00000', '2 Probe Road', 'Unit 4', 'Pune', 'Maharashtra', '411001');
		INSERT INTO "clients" ("id","tenant_id","code","name","status","system_owned")
		VALUES (gen_random_uuid(), t, 'P-0077-B', 'probe b', 'departed', false);
		INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","phone","roles","is_primary")
		VALUES (gen_random_uuid(), t, c, 'Asha Rao', 'asha@example.invalid', '+91 98200 00001', ARRAY['operations','billing','returns'], true),
		       (gen_random_uuid(), t, c, 'Ravi', 'ravi@example.invalid', NULL, ARRAY[]::text[], false);
		INSERT INTO "sessions" ("id","tenant_id","user_id","kind","refresh_hash","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
		VALUES (gen_random_uuid(), t, u, 'web', 'h-0077', now(), now(), now(), 'client-departed');
		RAISE EXCEPTION USING ERRCODE = 'P0077', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0077: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0077' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'registered without a pincode', 'registered state not two digits', 'registered line2 alone',
		'return without a phone', 'return pincode not six digits', 'return line2 alone',
		'contact name untrimmed', 'contact email upper-case', 'contact email untrimmed', 'contact phone too long',
		'contact unknown role', 'contact duplicate role', 'contact null role',
		'second primary', 'duplicate email', 'unknown revoke reason'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'registered without a pincode' THEN 'clients_registered_address_format'
			WHEN 'registered state not two digits' THEN 'clients_registered_address_format'
			WHEN 'registered line2 alone' THEN 'clients_registered_address_format'
			WHEN 'return without a phone' THEN 'clients_return_address_format'
			WHEN 'return pincode not six digits' THEN 'clients_return_address_format'
			WHEN 'return line2 alone' THEN 'clients_return_address_format'
			WHEN 'contact name untrimmed' THEN 'client_contacts_name_format'
			WHEN 'contact email upper-case' THEN 'client_contacts_email_format'
			WHEN 'contact email untrimmed' THEN 'client_contacts_email_format'
			WHEN 'contact phone too long' THEN 'client_contacts_phone_format'
			WHEN 'contact unknown role' THEN 'client_contacts_roles_check'
			WHEN 'contact duplicate role' THEN 'client_contacts_roles_check'
			WHEN 'contact null role' THEN 'client_contacts_roles_check'
			WHEN 'second primary' THEN 'client_contacts_one_primary_unique'
			WHEN 'duplicate email' THEN 'client_contacts_client_email_unique'
			ELSE 'sessions_revoked_reason_check'
		END;
		BEGIN
			CASE probe
				WHEN 'registered without a pincode' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","registered_line1","registered_city","registered_state_code")
					VALUES (gen_random_uuid(), t, 'P-0077-C', 'p', 'l1', 'city', '27');
				WHEN 'registered state not two digits' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","registered_line1","registered_city","registered_state_code","registered_pincode")
					VALUES (gen_random_uuid(), t, 'P-0077-C', 'p', 'l1', 'city', 'MH', '400001');
				WHEN 'registered line2 alone' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","registered_line2")
					VALUES (gen_random_uuid(), t, 'P-0077-C', 'p', 'l2');
				WHEN 'return without a phone' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","return_contact_name","return_line1","return_city","return_state","return_pincode")
					VALUES (gen_random_uuid(), t, 'P-0077-C', 'p', 'n', 'l1', 'city', 'state', '400001');
				WHEN 'return pincode not six digits' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","return_contact_name","return_phone","return_line1","return_city","return_state","return_pincode")
					VALUES (gen_random_uuid(), t, 'P-0077-C', 'p', 'n', '1', 'l1', 'city', 'state', '4000');
				WHEN 'return line2 alone' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","return_line2")
					VALUES (gen_random_uuid(), t, 'P-0077-C', 'p', 'l2');
				WHEN 'contact name untrimmed' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email") VALUES (gen_random_uuid(), t, c, ' Asha', 'a1@example.invalid');
				WHEN 'contact email upper-case' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email") VALUES (gen_random_uuid(), t, c, 'Asha', 'A2@example.invalid');
				WHEN 'contact email untrimmed' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email") VALUES (gen_random_uuid(), t, c, 'Asha', ' a3@example.invalid');
				WHEN 'contact phone too long' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","phone") VALUES (gen_random_uuid(), t, c, 'Asha', 'a4@example.invalid', '012345678901234567890');
				WHEN 'contact unknown role' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles") VALUES (gen_random_uuid(), t, c, 'Asha', 'a5@example.invalid', ARRAY['sales']);
				WHEN 'contact duplicate role' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles") VALUES (gen_random_uuid(), t, c, 'Asha', 'a6@example.invalid', ARRAY['billing','billing']);
				WHEN 'contact null role' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","roles") VALUES (gen_random_uuid(), t, c, 'Asha', 'a7@example.invalid', ARRAY[NULL]::text[]);
				WHEN 'second primary' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email","is_primary")
					VALUES (gen_random_uuid(), t, c, 'Asha', 'a8@example.invalid', true), (gen_random_uuid(), t, c, 'Ravi', 'a9@example.invalid', true);
				WHEN 'duplicate email' THEN
					INSERT INTO "client_contacts" ("id","tenant_id","client_id","name","email")
					VALUES (gen_random_uuid(), t, c, 'Asha', 'a10@example.invalid'), (gen_random_uuid(), t, c, 'Ravi', 'a10@example.invalid');
				WHEN 'unknown revoke reason' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
					VALUES (gen_random_uuid(), t, u, 'web', now(), now(), now(), 'client-gone');
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0077: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "clients" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "client_contacts" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0077: a probe row survived.';
	END IF;
END $$;
